package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import android.media.*;import android.net.Uri;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Sandboxed preview surface: no EvaHost, file/content access, or remote networking. */
final class RichPreview {
 final WorkspacePreviewActivity host;final File source;final String kind;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler timer=new Handler(Looper.getMainLooper());WebView web;VideoView video;MediaPlayer audio;SeekBar seek;TextView status;Button play;boolean ready,interactive,destroyed,restoreScroll;volatile String documentHTML="",documentUrl="";int position,scroll;long stamp;
 RichPreview(WorkspacePreviewActivity a,File file,Bundle state){host=a;source=file;kind=DocumentPreview.kind(file);position=state==null?0:state.getInt("media-position",0);scroll=state==null?0:state.getInt("preview-scroll",0);a.clear();status=a.label("正在准备预览…",12);a.body.addView(status);if(kind.equals("audio")||kind.equals("video"))media();else if(kind.equals("unsupported")){status.setText("暂不支持在 Eva 内预览此格式。旧版 DOC/XLS/PPT 请先转换为 DOCX/XLSX/PPTX；可从右上角另存到手机。");}else document();}
 void document(){web=new WebView(host);web.setBackgroundColor(android.graphics.Color.WHITE);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setDomStorageEnabled(false);web.getSettings().setJavaScriptEnabled(kind.equals("markdown"));web.getSettings().setSupportZoom(true);web.getSettings().setBuiltInZoomControls(true);web.getSettings().setDisplayZoomControls(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri u=request.getUrl();if("preview.eva.invalid".equals(u.getHost())&&u.getFragment()!=null)return false;return true;}public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){return resource(request);}public void onPageFinished(WebView v,String url){if(restoreScroll){restoreScroll=false;v.post(()->{if(!destroyed)v.scrollTo(0,scroll);});}}public boolean onRenderProcessGone(WebView v,RenderProcessGoneDetail detail){if(!destroyed){host.body.removeView(v);v.destroy();web=null;status.setText("预览进程已退出，请返回重试或使用较小文件。");}return true;}});host.body.addView(web,new LinearLayout.LayoutParams(-1,0,1));if(kind.equals("html")){Button enable=host.button("启用 HTML 交互",()->new AlertDialog.Builder(host).setTitle("启用本地页面交互？").setMessage("允许这个文件和同目录脚本运行。预览不开放 Eva 接口，仍阻止网络访问。").setNegativeButton("取消",null).setPositiveButton("启用",(d,n)->{interactive=true;web.getSettings().setJavaScriptEnabled(true);load();}).show());host.header.addView(enable);}load();}
 void load(){stamp=source.lastModified();status.setText(kind.equals("office")?"结构与内容预览 · 不含完整 Office 排版、图表、动画或公式计算":"离线预览 · 远程资源与外部页面已阻止");worker.execute(()->{try{String content;boolean scripts=kind.equals("markdown")||interactive;if(kind.equals("office"))content=DocumentPreview.renderOffice(source);else{if(source.length()>1024*1024)throw new IOException("文本或 HTML 超过 1 MB 预览上限，请使用编辑器或拆分文件");byte[] raw;try(InputStream in=new FileInputStream(source)){raw=DocumentPreview.bounded(in,1024*1024);}String text=DocumentPreview.utf8(raw);if(kind.equals("markdown")){String json=org.json.JSONObject.quote(text).replace("<","\\u003c").replace("\u2028","\\u2028").replace("\u2029","\\u2029");content="<main id=markdown></main><script src=\"https://preview.eva.invalid/_eva/markdown.js\"></script><script>document.getElementById('markdown').innerHTML=markdownit({html:false,linkify:false,breaks:true}).render("+json+");</script>";}else if(kind.equals("html"))content=text;else if(kind.equals("svg"))content="<img alt=\"矢量图预览\" src=\"data:image/svg+xml;base64,"+android.util.Base64.encodeToString(raw,android.util.Base64.NO_WRAP)+"\">";else if(DocumentPreview.ext(source).equals("csv")||DocumentPreview.ext(source).equals("tsv"))content=DocumentPreview.csv(text,DocumentPreview.ext(source).equals("tsv")?'\t':',');else content="<pre>"+DocumentPreview.esc(text)+"</pre>";}if(content.length()>8*1024*1024)throw new IOException("预览内容过大，请拆分文档");String html=DocumentPreview.page(content,scripts);host.runOnUiThread(()->{if(!destroyed&&web!=null){String relative;try{relative=WorkspaceFiles.root(host).toPath().relativize(source.toPath()).toString().replace('\\','/');documentHTML=html;restoreScroll=true;documentUrl="https://preview.eva.invalid/workspace/"+Uri.encode(relative,"/");web.loadUrl(documentUrl);}catch(Exception e){status.setText("预览失败："+e.getMessage());}}});}catch(Exception e){host.runOnUiThread(()->{if(!destroyed)status.setText("无法预览："+e.getMessage());});}});}
 WebResourceResponse resource(WebResourceRequest r){try{Uri u=r.getUrl();if(!"https".equals(u.getScheme())||!"preview.eva.invalid".equals(u.getHost()))return denied();if(r.isForMainFrame()&&u.toString().equals(documentUrl))return new WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream(documentHTML.getBytes(java.nio.charset.StandardCharsets.UTF_8)));if("/_eva/markdown.js".equals(u.getPath())&&kind.equals("markdown"))return new WebResourceResponse("text/javascript","UTF-8",host.getAssets().open("eva-markdown.js"));String path=u.getPath();if(path==null||!path.startsWith("/workspace/"))return denied();File f=WorkspaceFiles.resolve(host,path.substring("/workspace/".length()));if(!f.toPath().startsWith(source.getParentFile().getCanonicalFile().toPath())||!f.isFile()||f.length()>4L*1024*1024)return denied();String ext=DocumentPreview.ext(f),mime=DocumentPreview.mime(f);if(ext.equals("css"))mime="text/css";else if(ext.equals("js")&&interactive)mime="text/javascript";else if(Arrays.asList("woff","woff2","ttf").contains(ext))mime="font/"+ext;else if(!mime.startsWith("image/"))return denied();return new WebResourceResponse(mime,null,new FileInputStream(f));}catch(Exception e){return denied();}}
 static WebResourceResponse denied(){return new WebResourceResponse("text/plain","UTF-8",403,"Forbidden",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
 void media(){status.setText("正在读取媒体信息…");play=host.button("播放",()->{if(!ready)return;if(video!=null){if(video.isPlaying()){video.pause();play.setText("播放");}else{video.start();play.setText("暂停");}}else if(audio!=null){if(audio.isPlaying()){audio.pause();play.setText("播放");}else{audio.start();play.setText("暂停");}}});play.setEnabled(false);if(kind.equals("video")){video=new VideoView(host);host.body.addView(video,new LinearLayout.LayoutParams(-1,0,1));MediaController controller=new MediaController(host);controller.setAnchorView(video);video.setMediaController(controller);video.setOnPreparedListener(player->{ready=true;video.seekTo(position);play.setEnabled(true);status.setText("视频预览 · "+time(player.getDuration()));});video.setOnErrorListener((p,what,extra)->{status.setText("无法播放：系统不支持此视频编码或文件已损坏，可另存后打开。");return true;});video.setVideoURI(Uri.fromFile(source));}else{TextView title=host.label(source.getName(),19);host.body.addView(title);seek=new SeekBar(host);host.body.addView(seek,new LinearLayout.LayoutParams(-1,-2));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){if(ready&&audio!=null)audio.seekTo(b.getProgress());}public void onProgressChanged(SeekBar b,int n,boolean user){}});worker.execute(()->{MediaPlayer player=new MediaPlayer();try{player.setDataSource(source.getCanonicalPath());player.prepare();host.runOnUiThread(()->{if(destroyed){player.release();return;}audio=player;ready=true;audio.seekTo(position);seek.setMax(audio.getDuration());play.setEnabled(true);audio.setOnCompletionListener(p->{play.setText("播放");});tick();});}catch(Exception e){player.release();host.runOnUiThread(()->{if(!destroyed)status.setText("无法播放：系统不支持此音频编码或文件已损坏，可另存后打开。");});}});}host.body.addView(play);}
 String time(int ms){return String.format(Locale.ROOT,"%d:%02d",ms/60000,ms/1000%60);}
 void tick(){if(destroyed||audio==null)return;int at=audio.getCurrentPosition();seek.setProgress(at);status.setText(time(at)+" / "+time(audio.getDuration()));timer.postDelayed(this::tick,500);}
 void pause(){if(web!=null)web.onPause();if(video!=null){position=video.getCurrentPosition();video.pause();}if(audio!=null){position=audio.getCurrentPosition();if(audio.isPlaying())audio.pause();}if(play!=null)play.setText("播放");}
 void resume(){if(web!=null){web.onResume();if(source.lastModified()!=stamp){scroll=web.getScrollY();load();}}}
 void save(Bundle out){out.putInt("preview-scroll",web==null?scroll:web.getScrollY());out.putInt("media-position",video!=null?video.getCurrentPosition():audio!=null?audio.getCurrentPosition():position);}
 void destroy(){destroyed=true;timer.removeCallbacksAndMessages(null);worker.shutdownNow();if(web!=null){host.body.removeView(web);web.stopLoading();web.destroy();web=null;}if(video!=null)video.stopPlayback();if(audio!=null){audio.release();audio=null;}}
}
